window.BW_LOGO="data:image/jpeg;base64,";window.BW_LOGO_SM="data:image/jpeg;base64,";
document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("[data-logo]").forEach(function(e){var u=e.getAttribute("data-logo")==="sm"?window.BW_LOGO_SM:window.BW_LOGO;if(e.tagName==="LINK")e.href=u;else e.src=u;});});
